fn fib_tail(n: Int, a: Int, b: Int) -> Int
  requires: n >= 0;
{
  if n == 0 { return a; }
  return fib_tail(n - 1, b, a + b);
}

fn fibonacci(n: Int) -> Int
  requires: n >= 0;
{
  return fib_tail(n, 0, 1);
}

fn main() -> Int {
  return fibonacci(10);
}
